// writeTopicsFile overwrites <dir>/Topics.cs with the assembled topic
// declarations.
func writeTopicsFile(dir string, m *Model) error {
	return renderTo(filepath.Join(dir, "Topics.cs"), topicsFile, m)
}

// writeDevelopmentFile overwrites <dir>/<ProjectName>Development.cs with the
// assembled development definition: the platform-service mocks plus one file
// resolution per connector. Like the system class it refuses to create the
// file — a missing placeholder means the template release predates
// development definitions (and its pinned Intropy.Topology has no
// IDevelopmentDefinition), so it reports false and the caller degrades the
// connector and system-class shapes to that era instead of failing.
func writeDevelopmentFile(dir string, m *Model, warnf func(format string, args ...any)) (bool, error) {
	path := filepath.Join(dir, m.ProjectName+"Development.cs")
	if _, err := os.Stat(path); err != nil {
		warnf("template rendered no %sDevelopment.cs placeholder — this release predates development definitions; generating connectors with local file transports (upgrade with --version <newer tag> for deployed transports and local service mocks)", m.ProjectName)
		return false, nil
	}
	return true, renderTo(path, developmentFile, m)
}

// writeConnectorsFile overwrites <dir>/Connectors.cs with the assembled
// connector declarations. Like the system class it refuses to create the
// file — but here a missing placeholder means the template release predates
// connectors entirely, so the system is generated without From/To instead of
// failing: it reports false and the caller degrades the system class the
// same way. withDevelopment=false (a release with connectors but no
// development definitions) keeps the era's local file transports; otherwise
// connectors declare their deployed transport shape and the development
// definition owns the local resolution.
func writeConnectorsFile(dir string, m *Model, withDevelopment bool, warnf func(format string, args ...any)) (bool, error) {
	path := filepath.Join(dir, "Connectors.cs")
	if _, err := os.Stat(path); err != nil {
		warnf("template rendered no Connectors.cs placeholder — this release predates connectors; generating the system without From/To (upgrade with --version <newer tag> to wire them)")
		return false, nil
	}
	tmpl := connectorsFile
	if !withDevelopment {
		tmpl = connectorsFileLegacy
	}
	return true, renderTo(path, tmpl, m)
}

// writeSystemClassFile overwrites <dir>/<SystemClass>.cs with the assembled
// system definition. It refuses to create the file: the rendered template
// must have left the placeholder, or its name derivation disagrees with
// this CLI and the write would add a second ISystemDefinition instead of
// replacing the placeholder. withConnectors=false (a template release that
// predates Connectors.cs) omits the From/To calls; withDevelopment=false
// (a release that predates development definitions, whose skeleton ships no
// Services.cs) omits the Uses calls.
func writeSystemClassFile(dir string, m *Model, withConnectors, withDevelopment bool) error {
	path := filepath.Join(dir, m.SystemClass+".cs")
	if _, err := os.Stat(path); err != nil {
		return fmt.Errorf("template rendered no %s.cs placeholder: the template's systemClass derivation disagrees with this CLI; upgrade intropy or pass --version <compatible tag>", m.SystemClass)
	}

	views := make([]componentView, len(m.Components))
	fieldByKey := map[TopicKey]string{}
	for _, t := range m.Topics {
		fieldByKey[t.TopicKey] = t.Field
	}
	connectorField := map[string]string{}
	for _, c := range m.Connectors {
		connectorField[c.Name] = c.Field
	}
	for i, c := range m.Components {
		v := componentView{AppID: c.AppID}
		topicField := fieldByKey[c.Topic]
		field, hasConnector := connectorField[c.Connector]
		hasConnector = hasConnector && withConnectors
		if c.Kind == intropytemplate.BlockKindExtractor {
			v.Add = "AddExtractor"
			if hasConnector {
				v.Calls = append(v.Calls, ".From(Connectors."+field+")")
			}
			v.Calls = append(v.Calls, ".Publishes(Topics."+topicField+")")
			v.Calls = append(v.Calls, usesCalls(withDevelopment)...)
			// Gated on the same signal as From/To: a template release that
			// predates Connectors.cs also pins an Intropy.Topology without
			// WithSchedule, so the degraded shape must not call it.
			if withConnectors {
				v.Calls = append(v.Calls, `.WithSchedule("`+defaultExtractorSchedule+`")`)
			}
		} else {
			v.Add = "AddLoader"
			v.Calls = append(v.Calls, ".Subscribes(Topics."+topicField+")")
			if hasConnector {
				v.Calls = append(v.Calls, ".To(Connectors."+field+")")
			}
			v.Calls = append(v.Calls, usesCalls(withDevelopment)...)
		}
		views[i] = v
	}

	return renderTo(path, systemClassFile, struct {
		Name        string
		SystemClass string
		Components  []componentView
	}{m.Name, m.SystemClass, views})
}

// usesCalls is the platform-service wiring every block gets: the framework's
// block builders require idempotency and business-incident routing, and the
// skeleton's Services.cs declares both refs. Gated on the development era —
// earlier skeletons ship no Services.cs and pin an Intropy.Topology without
// Uses.
func usesCalls(withDevelopment bool) []string {
	if !withDevelopment {
		return nil
	}
	return []string{".Uses(Services.Idempotency)", ".Uses(Services.BusinessIncidents)"}
}

func renderTo(path string, tmpl *template.Template, data any) error {
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, data); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	return nil
}

package template

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"strings"
)

// maxDependencyDepth bounds transitive dependency chains. Real chains are
// one level deep (component → shared library); the cap only exists to turn
// an authoring cycle that survives the visited-set check into a clear error.
const maxDependencyDepth = 5

// DependencyResult reports what Create did about one declared dependency.
// Part of CreateResult's additive-only JSON contract.
type DependencyResult struct {
	Template  string `json:"template"`
	OutputDir string `json:"outputDir"`
	Action    string `json:"action"` // "created" | "exists"
}

// depContext carries the per-run state shared by every dependency render:
// the extracted templates repo (all templates of the resolved tag are
// already on disk) and a visited set so a diamond — two templates declaring
// the same sibling — renders it once.
type depContext struct {
	repoRoot string
	owner    string
	repo     string
	version  string
	stderr   io.Writer
	visited  map[string]bool
}

// processDependencies renders every spec.dependencies entry of tmpl as a
// sibling of outputDir, recursively, skipping targets that already carry a
// matching scaffold record. It returns the records to embed in the parent's
// scaffold.json and the results for CreateResult.
func processDependencies(tmpl *Template, values map[string]any, outputDir string, dc *depContext, depth int) ([]DependencyRecord, []DependencyResult, error) {
	if len(tmpl.Spec.Dependencies) == 0 {
		return nil, nil, nil
	}
	if depth >= maxDependencyDepth {
		return nil, nil, fmt.Errorf("dependency chain exceeds %d levels — check spec.dependencies for cycles", maxDependencyDepth)
	}

	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		return nil, nil, fmt.Errorf("absolute path for %s: %w", outputDir, err)
	}
	parentDir := filepath.Dir(absOut)

	var records []DependencyRecord
	var results []DependencyResult
	for _, dep := range tmpl.Spec.Dependencies {
		name, err := renderExpr(dep.Output, values)
		if err != nil {
			return nil, nil, fmt.Errorf("dependency %s: render output: %w", dep.Template, err)
		}
		if err := validateDependencyOutput(name); err != nil {
			return nil, nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
		}
		depDir := filepath.Join(parentDir, name)
		records = append(records, DependencyRecord{Template: dep.Template, Dir: path.Join("..", name)})

		if dc.visited[depDir] {
			// Another dependency in this same run already claimed the
			// directory; it was rendered (or skipped) there.
			continue
		}
		dc.visited[depDir] = true

		depValues, err := renderDependencyValues(dep, values)
		if err != nil {
			return nil, nil, err
		}

		existing, err := dependencyDirScaffold(depDir, dep.Template)
		if err != nil {
			return nil, nil, err
		}
		if existing != nil {
			warnDependencyDrift(dc.stderr, name, dep, depValues, existing.Values)
			fmt.Fprintf(dc.stderr, "dependency %s already scaffolded from %s — skipped\n", name, dep.Template)
			results = append(results, DependencyResult{Template: dep.Template, OutputDir: depDir, Action: "exists"})
			continue
		}

		created, err := renderDependency(dep, name, depDir, depValues, dc, depth)
		if err != nil {
			return nil, nil, err
		}
		results = append(results, created...)
	}
	return records, results, nil
}

// renderDependency scaffolds one dependency into depDir: resolve its values
// without prompting, render its skeleton, recurse into its own
// dependencies, and write its scaffold record. It returns the result for
// this dependency followed by any transitive ones.
func renderDependency(dep DependencySpec, name, depDir string, sets map[string]any, dc *depContext, depth int) ([]DependencyResult, error) {
	depRoot := filepath.Join(dc.repoRoot, dep.Template)
	depTmpl, err := LoadTemplate(filepath.Join(depRoot, templateManifestName))
	if err != nil {
		return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
	}

	// No prompter: a dependency render must never block on interactive
	// input, since whether it runs at all depends on the target directory.
	values, err := Resolve(depTmpl, nil, nil, sets, nil)
	if err != nil {
		return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
	}

	// --force never propagates to dependencies: overwriting a shared
	// project that other components already reference is destructive at a
	// distance. Regenerating one is an explicit `int create <template> --force`.
	if err := renderCreateOutput(depRoot, dep.Template, depDir, false, values); err != nil {
		return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
	}

	subRecords, subResults, err := processDependencies(depTmpl, values, depDir, dc, depth+1)
	if err != nil {
		return nil, err
	}

	if err := WriteScaffold(depDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      dep.Template,
		Owner:         dc.owner,
		Repo:          dc.repo,
		Version:       dc.version,
		Values:        values,
		Role:          roleFromLabels(depTmpl.Metadata.Labels),
		BlockKind:     blockKindFromLabels(depTmpl.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(depTmpl.Metadata.Labels),
		DependsOn:     subRecords,
	}); err != nil {
		return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
	}

	fmt.Fprintf(dc.stderr, "created dependency %s from template %s\n", name, dep.Template)
	own := DependencyResult{Template: dep.Template, OutputDir: depDir, Action: "created"}
	return append([]DependencyResult{own}, subResults...), nil
}

// renderDependencyValues renders the dependency's values map against the
// parent's resolved values. Every rendered value is a string; Resolve's
// schema-type coercion turns them into booleans/integers where the
// dependency's parameters call for it.
func renderDependencyValues(dep DependencySpec, parentValues map[string]any) (map[string]any, error) {
	out := make(map[string]any, len(dep.Values))
	for k, expr := range dep.Values {
		rendered, err := renderExpr(expr, parentValues)
		if err != nil {
			return nil, fmt.Errorf("dependency %s: render values.%s: %w", dep.Template, k, err)
		}
		out[k] = rendered
	}
	return out, nil
}

// dependencyDirScaffold classifies the dependency target directory. It
// returns the existing scaffold record when the directory is already managed
// by the same template (the skip case), nil when the directory is missing or
// empty (the render case), and an error for anything else — a foreign
// template's project or an unmanaged non-empty directory is never touched.
func dependencyDirScaffold(dir, wantTemplate string) (*Scaffold, error) {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return nil, nil
	case err != nil:
		return nil, err
	case !info.IsDir():
		return nil, fmt.Errorf("dependency target %s exists and is not a directory", dir)
	}

	scaffoldPath := filepath.Join(dir, filepath.FromSlash(ScaffoldRelPath))
	if _, err := os.Stat(scaffoldPath); err == nil {
		s, err := LoadScaffold(scaffoldPath)
		if err != nil {
			return nil, err
		}
		if s.Template != wantTemplate {
			return nil, fmt.Errorf("dependency target %s is already scaffolded from template %q, expected %q", dir, s.Template, wantTemplate)
		}
		return s, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}

	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	if len(entries) > 0 {
		return nil, fmt.Errorf("dependency target %s is not empty and has no %s — refusing to overwrite an unmanaged directory", dir, ScaffoldRelPath)
	}
	return nil, nil
}

// warnDependencyDrift compares the values this render would have passed to
// the dependency with what its scaffold record holds, and warns on
// mismatches. Drift is informational: the existing project wins.
func warnDependencyDrift(stderr io.Writer, name string, dep DependencySpec, want map[string]any, recorded map[string]any) {
	var drifted []string
	for k, v := range want {
		rec, ok := recorded[k]
		if !ok {
			continue
		}
		if fmt.Sprint(rec) != fmt.Sprint(v) {
			drifted = append(drifted, fmt.Sprintf("%s (recorded %v, this component derived %v)", k, rec, v))
		}
	}
	if len(drifted) > 0 {
		fmt.Fprintf(stderr, "warning: dependency %s (%s) was scaffolded with different values: %s\n", name, dep.Template, strings.Join(drifted, "; "))
	}
}

// validateDependencyOutput rejects rendered output names that are not a
// plain single path segment, so a dependency can only ever land as a direct
// sibling of the component.
func validateDependencyOutput(name string) error {
	if name == "" {
		return errors.New("output rendered to an empty string")
	}
	if name != filepath.Clean(name) || name == "." || name == ".." ||
		strings.HasPrefix(name, ".") || strings.ContainsAny(name, `/\`) || filepath.IsAbs(name) {
		return fmt.Errorf("output %q must be a single path segment (no separators, no leading dot)", name)
	}
	return nil
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.dev/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.dev/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in" or "out").
	// Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.dev/data-flow"

	// BlockKindExtractor and BlockKindLoader are the block kinds `sys
	// create` knows how to assemble.
	BlockKindExtractor = "extractor"
	BlockKindLoader    = "loader"
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.dev/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.dev/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.dev/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}
